import { cn } from "cn"

/**
 * The compact first-run card for a list page ("Add your products"): what goes
 * here, one primary and one secondary action, and up to four media tiles
 * showing the kind of thing that will fill it. The tiles drop below the text
 * on narrow containers (container query, so it follows its column).
 */
export function EmptyStateCard({
  title,
  description,
  actions,
  tiles = [],
  className,
}: {
  title: React.ReactNode
  description?: React.ReactNode
  actions?: React.ReactNode
  /** Up to four decorative tiles (images or icons). */
  tiles?: React.ReactNode[]
  className?: string
}) {
  return (
    <section
      data-slot="empty-state-card"
      className={cn("@container rounded-xl bg-card shadow-border", className)}
    >
      <div className="flex flex-col gap-8 p-6 @2xl:flex-row @2xl:items-center @2xl:p-10">
        <div className="flex min-w-0 flex-1 flex-col gap-1">
          <h2 className="font-heading text-lg font-semibold tracking-tight">
            {title}
          </h2>
          {description && (
            <p className="text-sm text-muted-foreground">{description}</p>
          )}
          {actions && (
            <div className="mt-4 flex flex-wrap items-center gap-2">
              {actions}
            </div>
          )}
        </div>
        {tiles.length > 0 && (
          <div
            aria-hidden
            className="grid w-full max-w-xs grid-cols-2 gap-2 @2xl:w-64"
          >
            {tiles.slice(0, 4).map((tile, i) => (
              <div
                key={i}
                className={cn(
                  "flex aspect-[4/3] items-center justify-center overflow-hidden rounded-lg bg-muted/70 transition-[opacity,translate] duration-500 ease-out starting:translate-y-1.5 starting:opacity-0 motion-reduce:transition-none [&_svg]:size-7 [&_svg]:text-muted-foreground",
                  i === 1 && "delay-75",
                  i === 2 && "delay-150",
                  i === 3 && "delay-200"
                )}
              >
                {tile}
              </div>
            ))}
          </div>
        )}
      </div>
    </section>
  )
}

import { cn } from "cn"

/**
 * First run of a product area ("Projects — Where it all starts"): the page is
 * the empty state. A two-line title (the second muted), pill actions, art
 * bleeding off the top-trailing corner over a faint column grid, and an
 * optional hint near the bottom. Everything enters once with a short fade-up
 * (`@starting-style`, no JS); reduced motion skips it.
 *
 *   <FeatureIntro
 *     title="Projects"
 *     tagline="Where it all starts"
 *     actions={<><Button>…</Button><Button variant="ghost">Import</Button></>}
 *     art={<IntroArt />}
 *     hint={<>Not sure where to start? <a>Use a template</a></>}
 *   />
 */
export function FeatureIntro({
  title,
  tagline,
  actions,
  art,
  hint,
  className,
}: {
  title: React.ReactNode
  tagline?: React.ReactNode
  actions?: React.ReactNode
  /** Decorative: hidden from assistive tech, clipped by the page edge. */
  art?: React.ReactNode
  hint?: React.ReactNode
  className?: string
}) {
  const enter =
    "transition-[opacity,translate] duration-500 ease-out starting:translate-y-2 starting:opacity-0 motion-reduce:transition-none"
  return (
    <section
      data-slot="feature-intro"
      className={cn(
        "relative isolate flex min-h-[32rem] flex-1 flex-col overflow-hidden",
        className
      )}
    >
      {/* Column grid, fading out toward the bottom. */}
      <div
        aria-hidden
        className="absolute inset-0 -z-10 bg-[repeating-linear-gradient(90deg,var(--border)_0_1px,transparent_1px_3rem)] opacity-50 [mask-image:linear-gradient(to_bottom,black,transparent_75%)]"
      />
      {art && (
        <div
          aria-hidden
          className={cn(
            "pointer-events-none absolute -top-6 -right-10 -z-10 w-[min(36rem,70%)] delay-100 starting:scale-95 sm:-right-6",
            enter,
            "transition-[opacity,translate,scale]"
          )}
        >
          {art}
        </div>
      )}
      <div className="flex flex-1 flex-col justify-center px-6 py-16 sm:ps-[clamp(2rem,18%,16rem)]">
        <div className={cn("max-w-md", enter)}>
          <h1 className="font-heading text-3xl font-semibold tracking-tight text-balance sm:text-4xl">
            {title}
            {tagline && (
              <span className="block text-muted-foreground">{tagline}</span>
            )}
          </h1>
          {actions && (
            <div className="mt-8 flex flex-wrap items-center gap-2 [--ds-radius-control:9999px]">
              {actions}
            </div>
          )}
        </div>
      </div>
      {hint && (
        <div className="px-6 pb-10 sm:ps-[clamp(2rem,18%,16rem)]">
          <p
            className={cn(
              "max-w-md text-sm text-muted-foreground delay-150 [&_strong]:font-medium [&_strong]:text-foreground",
              enter
            )}
          >
            {hint}
          </p>
        </div>
      )}
    </section>
  )
}

/**
 * Sample art for FeatureIntro: soft-lit shapes in the chart palette, drawn in
 * CSS (swap for your own renders). Each piece settles in a few ms apart.
 */
export function IntroArt() {
  const piece =
    "absolute transition-[opacity,translate,rotate] duration-700 ease-out starting:translate-y-4 starting:opacity-0 motion-reduce:transition-none"
  const light =
    "radial-gradient(circle at 30% 25%, oklch(1 0 0 / 0.75), transparent 45%)"
  return (
    <div className="relative aspect-[4/3] w-full">
      <span
        className={cn(piece, "top-[8%] left-[8%] h-[52%] w-[34%] rotate-[-12deg] rounded-[40%_40%_18%_18%] shadow-xl")}
        style={{
          background: `${light}, linear-gradient(160deg, var(--ds-chart-4), var(--ds-chart-2) 45%, var(--ds-chart-7))`,
        }}
      />
      <span
        className={cn(piece, "top-[2%] left-[52%] size-[22%] rotate-[18deg] rounded-[28%] shadow-lg delay-75")}
        style={{
          background: `${light}, linear-gradient(135deg, var(--ds-chart-3), oklch(0.35 0.06 200))`,
        }}
      />
      <span
        className={cn(piece, "top-[10%] right-[2%] h-[38%] w-[24%] rotate-[14deg] rounded-[32%] opacity-90 shadow-xl delay-150")}
        style={{
          background: `${light}, linear-gradient(180deg, var(--ds-chart-1), oklch(0.35 0.15 262))`,
        }}
      />
      <span
        className={cn(piece, "top-[52%] left-[44%] size-[24%] rotate-[-8deg] rounded-[30%] shadow-lg delay-200")}
        style={{
          background: `${light}, linear-gradient(140deg, var(--ds-chart-6), oklch(0.35 0.12 145))`,
        }}
      />
      <span
        className={cn(piece, "top-[46%] right-[-4%] h-[44%] w-[32%] rounded-[45%_45%_38%_38%] shadow-xl delay-300")}
        style={{
          background: `${light}, linear-gradient(170deg, var(--ds-chart-4), oklch(0.5 0.12 55))`,
        }}
      />
    </div>
  )
}

"use client"

import * as React from "react"
import { cn } from "cn"
import { CheckIcon, ChevronDownIcon, XIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"

export type ChecklistItem = {
  id: string
  title: string
  description: React.ReactNode
  /** The action that completes it ("Create project"). */
  action?: { label: string; href?: string; onClick?: () => void }
  done: boolean
}

/**
 * "Get started" on the dashboard: progress, then the tasks. The next open task
 * is expanded with its action; done tasks collapse to a struck line with a
 * check. Any task can be opened. Hide it with the X; when every task is done
 * it says so and offers to go away.
 */
export function GetStartedChecklist({
  title = "Get started",
  items,
  onDismiss,
  className,
}: {
  title?: React.ReactNode
  items: ChecklistItem[]
  onDismiss?: () => void
  className?: string
}) {
  const nextOpen = items.find((item) => !item.done)?.id
  // Follows the next open task until someone picks one.
  const [picked, setPicked] = React.useState<string | null>(null)
  const expanded = picked ?? nextOpen
  const done = items.filter((item) => item.done).length
  const complete = done === items.length

  return (
    <section
      aria-labelledby="get-started-title"
      className={cn("rounded-xl bg-card shadow-border", className)}
    >
      <header className="flex items-start gap-4 p-5 pb-4">
        <div className="flex min-w-0 flex-1 flex-col gap-3">
          <div className="flex items-baseline justify-between gap-3">
            <h2 id="get-started-title" className="font-heading font-semibold">
              {complete ? "You're all set" : title}
            </h2>
            <span className="text-sm text-muted-foreground tabular-nums">
              {done} of {items.length}
            </span>
          </div>
          <div
            role="progressbar"
            aria-label="Setup progress"
            aria-valuemin={0}
            aria-valuemax={items.length}
            aria-valuenow={done}
            className="flex gap-1"
          >
            {items.map((item) => (
              <span
                key={item.id}
                className={cn(
                  "h-1.5 flex-1 rounded-full bg-muted transition-colors duration-300",
                  item.done && "bg-tone-green"
                )}
              />
            ))}
          </div>
        </div>
        {onDismiss && (
          <Tooltip>
            <TooltipTrigger
              render={
                <Button
                  variant="ghost"
                  size="icon-sm"
                  aria-label="Hide checklist"
                  onClick={onDismiss}
                  className="-me-1.5 -mt-1"
                />
              }
            >
              <XIcon />
            </TooltipTrigger>
            <TooltipContent>Hide checklist</TooltipContent>
          </Tooltip>
        )}
      </header>
      <ul className="flex flex-col border-t p-2">
        {items.map((item) => {
          const open = item.id === expanded
          return (
            <li key={item.id} data-done={item.done || undefined} className="group/task">
              <button
                type="button"
                aria-expanded={open}
                onClick={() => setPicked(open ? "" : item.id)}
                className="flex w-full items-center gap-3 rounded-lg p-2.5 text-start focus-ring transition-colors hover:bg-muted/60"
              >
                <span
                  className={cn(
                    "flex size-5 shrink-0 items-center justify-center rounded-full border border-dashed border-muted-foreground/50 transition-[background-color,border-color] duration-200",
                    "group-data-done/task:border-solid group-data-done/task:border-tone-green group-data-done/task:bg-tone-green group-data-done/task:text-background"
                  )}
                >
                  <CheckIcon className="size-3 scale-50 opacity-0 transition-[opacity,scale] duration-200 ease-out group-data-done/task:scale-100 group-data-done/task:opacity-100" />
                </span>
                <span className="min-w-0 flex-1 text-sm font-medium group-data-done/task:text-muted-foreground group-data-done/task:line-through group-data-done/task:decoration-muted-foreground/40">
                  {item.title}
                  <span className="sr-only">{item.done ? ", done" : ""}</span>
                </span>
                <ChevronDownIcon
                  className={cn(
                    "size-4 shrink-0 text-muted-foreground transition-transform duration-200 ease-out motion-reduce:transition-none",
                    open && "rotate-180"
                  )}
                />
              </button>
              {/* grid 0fr→1fr animates the height without measuring it. */}
              <div
                className={cn(
                  "grid transition-[grid-template-rows,opacity] duration-200 ease-out motion-reduce:transition-none",
                  open ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0"
                )}
                inert={!open}
              >
                <div className="overflow-hidden">
                  <div className="flex flex-col items-start gap-3 ps-10 pe-3 pb-3 text-sm text-muted-foreground">
                    <p>{item.description}</p>
                    {item.action && !item.done && (
                      <Button
                        size="sm"
                        onClick={item.action.onClick}
                        {...(item.action.href && {
                          render: <a href={item.action.href} />,
                          nativeButton: false,
                        })}
                      >
                        {item.action.label}
                      </Button>
                    )}
                  </div>
                </div>
              </div>
            </li>
          )
        })}
      </ul>
    </section>
  )
}

"use client"

import * as React from "react"
import { cn } from "cn"
import { ArrowLeftIcon, CheckIcon, PartyPopperIcon } from "lucide-react"
import { z } from "zod"

import { Button } from "@/components/ui/button"
import {
  Form,
  FormBanner,
  FormField,
  FormSubmit,
  useZodForm,
} from "@/components/ui/form"
import { IconTile } from "@/components/ui/icon-tile"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
  InputGroupText,
} from "@/components/ui/input-group"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Textarea } from "@/components/ui/textarea"
import { setSearchParams, useUrlState } from "@/hooks/use-url-state"

// --- Schemas ---------------------------------------------------------------------

const slugify = (value: string) =>
  value
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 40)

const workspaceSchema = z.object({
  name: z.string().trim().min(2, "Name needs at least 2 characters"),
  slug: z
    .string()
    .trim()
    .min(2, "The URL needs at least 2 characters")
    .regex(/^[a-z0-9-]+$/, "Use lowercase letters, numbers and dashes"),
  region: z.enum(["fra", "iad", "gru", "sin"]),
})

const emailList = z.string().transform((value, ctx) => {
  const emails = value
    .split(/[\s,;]+/)
    .map((e) => e.trim())
    .filter(Boolean)
  const invalid = emails.filter((e) => !z.email().safeParse(e).success)
  if (invalid.length)
    ctx.addIssue({
      code: "custom",
      message: `Check ${invalid.length === 1 ? "this address" : "these addresses"}: ${invalid.join(", ")}`,
    })
  return [...new Set(emails)]
})

const teamSchema = z.object({
  emails: emailList,
  role: z.enum(["member", "admin"]),
})

const planSchema = z.object({ plan: z.enum(["hobby", "pro", "enterprise"]) })

export type SetupValues = {
  workspace: z.output<typeof workspaceSchema>
  team: z.output<typeof teamSchema>
  plan: z.output<typeof planSchema>
}

const STEPS = [
  { id: "workspace", title: "Workspace", description: "Name and URL" },
  { id: "team", title: "Team", description: "Invite people" },
  { id: "plan", title: "Plan", description: "Pick what fits" },
] as const
type StepId = (typeof STEPS)[number]["id"] | "done"

const REGIONS = [
  { value: "fra", label: "Frankfurt (eu-central)" },
  { value: "iad", label: "Virginia (us-east)" },
  { value: "gru", label: "São Paulo (sa-east)" },
  { value: "sin", label: "Singapore (ap-southeast)" },
]

const ROLES = [
  { value: "member", label: "Member" },
  { value: "admin", label: "Admin" },
]

const PLANS = [
  { value: "hobby", label: "Hobby", price: "Free", description: "3 projects, 1 seat" },
  { value: "pro", label: "Pro", price: "$24 / seat", description: "Unlimited projects, previews, audit log" },
  { value: "enterprise", label: "Enterprise", price: "Custom", description: "SSO, SLA and a success manager" },
]

// --- Pieces ----------------------------------------------------------------------

/** Step list: done steps get a check and can be revisited, upcoming ones can't. */
function Stepper({
  current,
  completed,
  onGo,
}: {
  current: number
  completed: number
  onGo: (index: number) => void
}) {
  return (
    <ol className="flex gap-2 md:flex-col md:gap-1">
      {STEPS.map((step, i) => {
        const done = i < completed
        const active = i === current
        return (
          <li key={step.id} className="min-w-0 flex-1 md:flex-none">
            <button
              type="button"
              disabled={!done && !active}
              aria-current={active ? "step" : undefined}
              onClick={() => onGo(i)}
              className="group/step flex w-full items-center gap-3 rounded-lg p-1.5 text-start focus-ring transition-colors enabled:hover:bg-muted/60 disabled:cursor-default md:p-2"
            >
              <span
                className={cn(
                  "flex size-7 shrink-0 items-center justify-center rounded-full border text-xs font-medium tabular-nums transition-colors duration-200",
                  done && "border-primary bg-primary text-primary-foreground",
                  active && "border-primary text-foreground",
                  !done && !active && "text-muted-foreground"
                )}
              >
                {done ? <CheckIcon className="size-3.5" /> : i + 1}
              </span>
              <span className="hidden min-w-0 md:block">
                <span
                  className={cn(
                    "block text-sm font-medium",
                    !done && !active && "text-muted-foreground"
                  )}
                >
                  {step.title}
                </span>
                <span className="block text-xs text-muted-foreground">
                  {step.description}
                </span>
              </span>
            </button>
          </li>
        )
      })}
    </ol>
  )
}

function StepHeader({ title, description }: { title: string; description: string }) {
  return (
    <div className="flex flex-col gap-1">
      <h1 className="font-heading text-2xl font-semibold tracking-tight">{title}</h1>
      <p className="text-muted-foreground">{description}</p>
    </div>
  )
}

function StepFooter({
  onBack,
  onSkip,
  submitLabel = "Continue",
}: {
  onBack?: () => void
  onSkip?: () => void
  submitLabel?: string
}) {
  return (
    <div className="flex items-center gap-2 border-t pt-6">
      {onBack && (
        <Button type="button" variant="ghost" onClick={onBack}>
          <ArrowLeftIcon data-icon="inline-start" />
          Back
        </Button>
      )}
      <div className="ms-auto flex items-center gap-2">
        {onSkip && (
          <Button type="button" variant="ghost" onClick={onSkip}>
            Skip for now
          </Button>
        )}
        <FormSubmit hotkey="Mod+Enter" showHotkey>
          {submitLabel}
        </FormSubmit>
      </div>
    </div>
  )
}

// --- Steps -----------------------------------------------------------------------

function WorkspaceStep({
  defaults,
  onNext,
}: {
  defaults?: SetupValues["workspace"]
  onNext: (values: SetupValues["workspace"]) => void
}) {
  const form = useZodForm(workspaceSchema, {
    defaultValues: defaults ?? { name: "", slug: "", region: "fra" },
  })
  // The URL follows the name until someone edits it by hand.
  const [slugEdited, setSlugEdited] = React.useState(!!defaults)
  return (
    <Form form={form} onSubmit={onNext} className="flex flex-col gap-6">
      <StepHeader
        title="Create your workspace"
        description="This is where your projects and team live. You can rename it later."
      />
      <FormBanner />
      <FormField
        name="name"
        label="Workspace name"
        required
        render={({ onChange, ...field }) => (
          <Input
            placeholder="Acme"
            autoComplete="organization"
            onChange={(event) => {
              onChange(event)
              if (!slugEdited)
                form.setValue("slug", slugify(event.target.value), {
                  shouldValidate: form.formState.isSubmitted,
                })
            }}
            {...field}
          />
        )}
      />
      <FormField
        name="slug"
        label="URL"
        required
        description="Letters, numbers and dashes."
        render={({ onChange, ...field }) => (
          <InputGroup>
            <InputGroupAddon>
              <InputGroupText>acme.app/</InputGroupText>
            </InputGroupAddon>
            <InputGroupInput
              spellCheck={false}
              onChange={(event) => {
                setSlugEdited(true)
                onChange(event)
              }}
              {...field}
            />
          </InputGroup>
        )}
      />
      <FormField
        name="region"
        label="Data region"
        description="Where your data is stored. Pick the one closest to your users."
        render={({ value, onChange, id, ...field }) => (
          <Select items={REGIONS} value={value} onValueChange={onChange} id={id}>
            <SelectTrigger id={id} className="w-full" {...field}>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {REGIONS.map((r) => (
                <SelectItem key={r.value} value={r.value}>
                  {r.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}
      />
      <StepFooter />
    </Form>
  )
}

function TeamStep({
  defaults,
  onNext,
  onBack,
}: {
  defaults?: z.input<typeof teamSchema>
  onNext: (values: SetupValues["team"]) => void
  onBack: () => void
}) {
  const form = useZodForm(teamSchema, {
    defaultValues: defaults ?? { emails: "", role: "member" },
  })
  return (
    <Form form={form} onSubmit={onNext} className="flex flex-col gap-6">
      <StepHeader
        title="Invite your team"
        description="Paste a list, one per line or separated by commas. They'll get an email to join."
      />
      <FormField
        name="emails"
        label="Email addresses"
        render={(field) => (
          <Textarea
            rows={4}
            spellCheck={false}
            placeholder={"ana@acme.com\nmarco@acme.com"}
            {...field}
          />
        )}
      />
      <FormField
        name="role"
        label="Role"
        description="Admins can manage billing and members."
        render={({ value, onChange, id, ...field }) => (
          <Select items={ROLES} value={value} onValueChange={onChange} id={id}>
            <SelectTrigger id={id} className="w-40" {...field}>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {ROLES.map((r) => (
                <SelectItem key={r.value} value={r.value}>
                  {r.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}
      />
      <StepFooter
        onBack={onBack}
        onSkip={() => onNext({ emails: [], role: "member" })}
        submitLabel="Send invites"
      />
    </Form>
  )
}

function PlanStep({
  defaults,
  onNext,
  onBack,
}: {
  defaults?: SetupValues["plan"]
  onNext: (values: SetupValues["plan"]) => Promise<void>
  onBack: () => void
}) {
  const form = useZodForm(planSchema, {
    defaultValues: defaults ?? { plan: "pro" },
  })
  return (
    <Form form={form} onSubmit={onNext} className="flex flex-col gap-6">
      <StepHeader
        title="Choose a plan"
        description="Pro starts with a 14-day trial. No card needed until it ends."
      />
      <FormBanner />
      <FormField
        name="plan"
        label="Plan"
        className="[&>[data-slot=field-label]]:sr-only"
        render={({ value, onChange, id, ...field }) => (
          <RadioGroup
            value={value}
            onValueChange={onChange}
            aria-label="Plan"
            className="gap-2"
            {...field}
          >
            {PLANS.map((plan) => (
              <label
                key={plan.value}
                className="flex cursor-pointer items-center gap-3 rounded-xl p-4 shadow-border transition-shadow hover:shadow-border-hover has-data-checked:ring-2 has-data-checked:ring-primary has-data-checked:shadow-none"
              >
                <RadioGroupItem value={plan.value} id={plan.value === value ? id : undefined} />
                <span className="min-w-0 flex-1">
                  <span className="block font-medium">{plan.label}</span>
                  <span className="block text-sm text-muted-foreground">
                    {plan.description}
                  </span>
                </span>
                <span className="text-sm font-medium tabular-nums">{plan.price}</span>
              </label>
            ))}
          </RadioGroup>
        )}
      />
      <StepFooter onBack={onBack} submitLabel="Create workspace" />
    </Form>
  )
}

// --- Wizard ----------------------------------------------------------------------

/**
 * First-run setup: workspace → team → plan → done. The step lives in the URL
 * (`?step=team`), so back/forward and refresh work; a step can't be opened
 * before the ones it depends on. Each step validates on its own, values are
 * kept when going back, and the content slides in the direction you move.
 * `onComplete` runs on the last step; a throw shows its message in a banner.
 */
export function SetupWizard({
  brand,
  onComplete,
  continueHref = "/",
}: {
  brand: React.ReactNode
  onComplete: (values: SetupValues) => Promise<void> | void
  /** Where "Go to dashboard" leads when done. */
  continueHref?: string
}) {
  const [stepParam] = useUrlState("step", "workspace", "push")
  const [values, setValues] = React.useState<Partial<SetupValues>>({})
  const [teamInput, setTeamInput] = React.useState<z.input<typeof teamSchema>>()
  const [direction, setDirection] = React.useState<1 | -1>(1)

  // Derive the step during render: never past the first unfinished one.
  const completed = values.workspace ? (values.team ? (values.plan ? 3 : 2) : 1) : 0
  const requested = STEPS.findIndex((s) => s.id === stepParam)
  const index =
    stepParam === "done" && completed === 3
      ? 3
      : Math.min(requested === -1 ? 0 : requested, completed)
  const step: StepId = index === 3 ? "done" : STEPS[index].id

  const go = (next: number) => {
    setDirection(next >= index ? 1 : -1)
    setSearchParams(
      { step: next === 0 ? null : next === 3 ? "done" : STEPS[next].id },
      "push"
    )
  }

  return (
    <div className="flex min-h-dvh flex-col bg-background text-foreground md:flex-row">
      <aside className="flex flex-col gap-6 border-b bg-sidebar p-4 md:w-72 md:border-e md:border-b-0 md:p-6">
        <div className="font-heading text-sm font-semibold">{brand}</div>
        {step !== "done" && (
          <Stepper current={index} completed={completed} onGo={go} />
        )}
        <p className="hidden text-xs text-muted-foreground md:mt-auto md:block">
          Step {Math.min(index + 1, 3)} of 3
        </p>
      </aside>
      <main className="flex flex-1 justify-center px-4 py-10 md:items-center md:px-10">
        <div
          key={step}
          style={{ "--dir": direction } as React.CSSProperties}
          className="w-full max-w-lg transition-[opacity,translate] duration-300 ease-out starting:translate-x-[calc(var(--dir)*1rem)] starting:opacity-0 motion-reduce:transition-none"
        >
          {step === "workspace" && (
            <WorkspaceStep
              defaults={values.workspace}
              onNext={(workspace) => {
                setValues((v) => ({ ...v, workspace }))
                go(1)
              }}
            />
          )}
          {step === "team" && (
            <TeamStep
              defaults={teamInput}
              onBack={() => go(0)}
              onNext={(team) => {
                setTeamInput({ emails: team.emails.join("\n"), role: team.role })
                setValues((v) => ({ ...v, team }))
                go(2)
              }}
            />
          )}
          {step === "plan" && (
            <PlanStep
              defaults={values.plan}
              onBack={() => go(1)}
              onNext={async (plan) => {
                const all = { ...values, plan } as SetupValues
                await onComplete(all)
                setValues(all)
                go(3)
              }}
            />
          )}
          {step === "done" && (
            <div className="flex flex-col items-start gap-6">
              <IconTile tone="green" size="lg">
                <PartyPopperIcon />
              </IconTile>
              <StepHeader
                title={`${values.workspace?.name} is ready`}
                description={
                  values.team?.emails.length
                    ? `We sent ${values.team.emails.length} invite${values.team.emails.length === 1 ? "" : "s"}. Next, create your first project.`
                    : "Next, create your first project. You can invite your team any time from Settings."
                }
              />
              <Button size="lg" render={<a href={continueHref} />} nativeButton={false}>
                Go to dashboard
              </Button>
            </div>
          )}
        </div>
      </main>
    </div>
  )
}
